about_disclaimer_title: "Avertissement",
about_disclaimer_purpose: "ps5upload est fourni uniquement à des fins de recherche, d'éducation, d'interopérabilité et de développement homebrew. Il n'est ni affilié, ni approuvé, ni lié à Sony Interactive Entertainment Inc. « PlayStation » et « PS5 » sont des marques de Sony Interactive Entertainment Inc., utilisées ici à des fins d'identification uniquement.",
about_disclaimer_piracy: "Utilisez-le uniquement avec du matériel qui vous appartient et des contenus que vous possédez légalement. Il ne doit pas servir à copier, distribuer ou exécuter des logiciels que vous n'avez pas le droit d'utiliser.",
about_disclaimer_risk: "Ce logiciel est fourni « en l'état », sans garantie d'aucune sorte. Utiliser une console modifiée peut l'endommager définitivement, détruire irrémédiablement vos sauvegardes et vos licences, et entraîner le bannissement de votre compte ou de votre console. Vous l'utilisez entièrement à vos risques et périls et assumez l'entière responsabilité des conséquences. Sauvegardez tout ce que vous ne pouvez pas vous permettre de perdre avant de commencer.",
