imgbrowse_title: "Explorer une image",
imgbrowse_explain: "Parcourez n'importe quelle image de jeu ou paquet que ps5upload lit (.exfat, .ffpkg, .ffpfs, .ffpfsc, ou un .pkg créé avec la clé de débogage) sur n'importe quel ordinateur, sans la monter. Enregistrez un fichier ou un dossier sur l'ordinateur, ou modifiez des fichiers et écrivez une copie modifiée : l'image ouverte n'est jamais modifiée.",
