imgbrowse_undo: "Annuler",
imgbrowse_copy_explain: "La copie est une toute nouvelle image du même type, écrite à côté de l'originale avec -edited dans son nom, puis relue et vérifiée. Cela prend à peu près autant de temps que la conversion du jeu. L'originale n'est pas modifiée.",
imgbrowse_write_copy: "Écrire la copie modifiée",
