imgbrowse_writing_copy: "Écriture d'une copie modifiée de {name}",
imgbrowse_copy_done: "Copie modifiée écrite et vérifiée",
imgbrowse_open_copy: "Explorer la copie",
localimage_explain: "L'image s'ouvre comme un lecteur ordinaire sur cet ordinateur : vous pouvez y ajouter, remplacer et supprimer des fichiers — des correctifs, par exemple — depuis le Finder ou l'Explorateur, exactement comme sur une clé USB. Les modifications sont enregistrées directement dans le fichier image. ps5upload n'écrit jamais lui-même dans l'image ; c'est votre système d'exploitation qui le fait. Éjectez-la ici quand vous avez terminé.",
localimage_filter: "Images disque",
