"pkglib.installAll.what": "Qu'est-ce que « Tout installer » ?",
"pkglib.installAll.whatBody": "« Tout installer » traite dans l'ordre tous les paquets prêts : jeu de base → mises à jour → DLC. Si vous avez deux mises à jour de la même version (ou deux DLC en conflit), utilisez la case à cocher de chaque ligne pour choisir celui que cette console doit installer — un seul par groupe. Décochez pour exclure ce groupe. Le bouton Installer d'une ligne n'installe toujours que ce paquet-là.",
