"fpkg.about": "Indique un dossier de jeu, ou une image de montage .exfat ou .ffpkg. Le convertisseur lit l’arborescence, vérifie que tout ce dont un paquet lançable a besoin est présent, et écrit un .pkg au format debug dans le dossier de sortie.",
"fpkg.aboutWhere": "La conversion s’exécute sur la machine qui héberge le moteur — cet ordinateur, un hôte Docker ou un appareil Android — pas sur la console. Rien n’arrive sur la console tant que tu n’installes pas le paquet — en flux depuis cet ordinateur, ou envoyé d’abord sur la PS5.",
"fpkg.aboutSource": "La source doit être une arborescence de jeu déjà déchiffrée. Une installation retail ne peut pas être extraite ici, et la vérification ci-dessous le dira si c’est ce que tu as choisi.",
"fpkg.aboutChecks": "Ce que la vérification contrôle",
"fpkg.checkEboot": "Un eboot.bin à la racine de l’arborescence — le module du titre. Ce doit être un ELF brut ou un SELF encapsulé ; un module signé retail ne peut pas être réempaqueté.",
"fpkg.checkParam": "sce_sys/param.json, et aucun sce_sys/param.sfo — un param.sfo envoie le chemin de lancement de la console vers la voie PS4.",
"fpkg.checkIcons": "Un identifiant de contenu de 36 caractères, les deux icônes et le module de droits sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Que la valeur DRM du paquet est standard. Une valeur gratuite ou évolutive fait verrouiller le titre par la console ; elle n’est réécrite que dans le paquet, et ton propre fichier n’est jamais modifié.",
"payloads_essentials_title": "Recommandés avec ps5upload",
"payloads_essentials_body": "Si tu configures une console pour la première fois, ces trois-là couvrent l’essentiel de ce qu’attend ps5upload : kstuff-lite (les patches noyau dont dépend la plupart des homebrews), ShadowMount+ (monter des images de jeux depuis le stockage) et nanoDNS (tenir la console à l’écart des mises à jour de Sony). Tout le reste de cette liste est facultatif.",
