kept_clean_title: "Supprimer ces fichiers de la PS5 ?",
kept_clean_body: "Tout le contenu de {path} ({size}) sera supprimé. Ce sont des restes que ps5upload peut recréer ; rien n'est touché dans votre bibliothèque de paquets ni dans vos sauvegardes.",
library_move_retry: "Réessayer le déplacement",
volumes_pkg_copies_here: "Les copies de paquets sont stockées ici",
volumes_store_pkg_copies: "Stocker les copies de paquets ici",
volumes_pkg_copies_hint: "Ce que fait ce choix : « Envoyer et installer » copie d'abord le fichier .pkg sur la PS5, puis installe depuis cette copie. Ceci définit seulement le disque qui conserve ces copies. Cela ne change pas l'endroit où les jeux sont installés (la PS5 le décide dans ses réglages de stockage), et « Diffuser et installer » ne garde aucune copie. Si le disque choisi n'est pas connecté, les copies vont dans le stockage interne.",
saves_auto_folder_label: "Dossier de sauvegarde",
captures: "Captures et clips",
captures_title: "Captures",
"arcpkg.choose": "Choisir une archive…",
"arcpkg.help": "Pour un .zip, .7z ou .rar qui contient un ou plusieurs fichiers .pkg, dans n'importe quel dossier. Seuls les paquets sont décompressés, directement sur la PS5 (rien n'est extrait sur cet ordinateur), puis installés un par un : le jeu de base avant sa mise à jour, puis les DLC. Un RAR en plusieurs parties (.part1.rar, .part2.rar…) fonctionne : choisissez la première partie et gardez les autres à côté. Un mot de passe est demandé quand un RAR en a besoin ; les ZIP et 7z protégés par mot de passe ne sont pas pris en charge.",
"arcpkg.keepsRunning": "Cela continue si vous ouvrez un autre écran ; c'est aussi visible dans Tâches.",
"arcpkg.notArchive": "Ce fichier n'est pas une archive .zip, .7z ou .rar.",
"arcpkg.pick": "Choisir une archive",
"arcpkg.title": "Installer les paquets d'une archive",
"install.library.title": "Copies de paquets sur la PS5",
"install.stream.file.help": "Choisissez un .pkg ou .fpkg, ou déposez-en un n'importe où sur cette fenêtre. Gardez l'application ouverte jusqu'à la fin de l'installation ; sa progression s'affiche dans la file ci-dessus et dans Tâches.",
"install.stream.file.title": "Installer un fichier de paquet",
"install.tab.stream.lead": "La PS5 installe directement depuis cet ordinateur ou depuis un lien. Aucune copie n'est placée d'abord sur la PS5, il n'y faut donc pas d'espace libre, et c'est la façon la plus fiable d'installer.",
"install.tab.upload.lead": "Le paquet est d'abord copié sur la PS5, puis installé depuis cette copie. À utiliser quand la PS5 ne peut pas joindre cet ordinateur (Diffuser échoue avec une erreur réseau), ou pour garder des paquets sur la PS5 et les réinstaller plus tard sans cet ordinateur.",
"install.upload.file.browser": "Copier un paquet vers la PS5 d'ici nécessite l'application de bureau. Dans l'interface web, utilisez Diffuser et installer, ou installez ci-dessous les paquets déjà présents sur la PS5.",
"install.upload.file.help": "Choisissez un .pkg ou .fpkg. La copie a besoin d'espace libre sur la PS5 pour tout le paquet et reste dans la liste ci-dessous jusqu'à ce que vous la retiriez.",
"install.upload.file.title": "Copier un paquet sur la PS5 et l'installer",
"linkcard.confirm.direct": "La PS5 télécharge elle-même le paquet depuis le lien et l'installe. Cet ordinateur n'est plus nécessaire une fois le téléchargement lancé, et la progression s'affiche sur la PS5 (Téléchargements), pas ici. Si la PS5 ne peut pas récupérer le lien, l'application le diffuse via cet ordinateur. Réinstaller par-dessus un jeu installé peut le supprimer si l'installeur de Sony échoue. N'utilisez qu'un lien de paquet de confiance que vous êtes autorisé à installer.",
"linkcard.confirm.download": "Cet ordinateur enregistre d'abord tout le paquet sur son disque, puis l'installe sur la PS5. Il doit rester éveillé jusqu'à la fin des deux étapes et a besoin d'espace libre pour le paquet. Réinstaller par-dessus un jeu installé peut le supprimer si l'installeur de Sony échoue. N'utilisez qu'un lien de paquet de confiance que vous êtes autorisé à installer.",
"linkcard.confirm.stream": "Cet ordinateur télécharge le paquet et le transmet directement à la PS5 ; il doit donc rester éveillé et connecté jusqu'à la fin de l'installation. Rien n'est enregistré sur le disque. Réinstaller par-dessus un jeu installé peut le supprimer si l'installeur de Sony échoue. N'utilisez qu'un lien de paquet de confiance que vous êtes autorisé à installer.",
"linkcard.confirm.title": "Installer depuis ce lien ?",
"linkcard.fact.awake": "Gardez cet ordinateur éveillé",
"linkcard.fact.can_close": "Vous pouvez fermer l'application",
"linkcard.fact.disk": "Nécessite de l'espace disque ici",
"linkcard.fact.no_disk": "Aucun espace disque requis",
"linkcard.fact.progress_here": "Progression affichée ici",
"linkcard.fact.progress_ps5": "Progression sur la PS5",
"linkcard.forget": "Retirer de la liste",
"linkcard.help": "Collez un lien de téléchargement direct vers un .pkg. Rien n'est copié d'abord sur la PS5, donc un jeu de 100 Go n'y demande aucun espace supplémentaire.",
"linkcard.how": "Comment le récupérer ?",
"linkcard.insecure": "Ignorer la vérification du certificat",
"linkcard.insecure_hint": "Pour votre propre serveur, ou un site dont le certificat est périmé. Cela s'applique ici parce que c'est cet ordinateur qui établit la connexion.",
"linkcard.install": "Installer depuis le lien",
"linkcard.mode.direct": "La PS5 le télécharge",
"linkcard.mode.direct_body": "La PS5 récupère le lien elle-même. Elle doit pouvoir atteindre le lien, et l'adresse doit être courte (l'application raccourcit une adresse longue, et doit alors rester ouverte).",
"linkcard.mode.download": "Télécharger ici d'abord, puis installer",
"linkcard.mode.download_body": "Cet ordinateur enregistre tout le paquet, puis l'installe. Le plus lent, mais un lien qui expire ou se coupe en route ne coûte qu'une nouvelle tentative de téléchargement.",
"linkcard.mode.stream": "Diffuser via cet ordinateur",
"linkcard.mode.stream_body": "Cet ordinateur télécharge sur plusieurs connexions et transmet directement à la PS5. Généralement le plus rapide, et cela fonctionne quand seul cet ordinateur peut atteindre le lien.",
"linkcard.name": "Nom (facultatif)",
"linkcard.name_hint": "Le nom s'affiche dans la file, dans Tâches et sous Liens récents à la place de l'adresse, pour distinguer les liens et relancer le bon.",
