"speedtest.verdict.hundred": "Cela ressemble à une liaison 100 Mbit, qui plafonne vers 11 Mo/s. Vérifiez le câble (Cat5e ou mieux) et que chaque port de switch ou de routeur sur le trajet est gigabit.",
"speedtest.verdict.mid": "Correct, mais en dessous de ce que donne un câble gigabit (90–115 Mo/s). Causes habituelles : du Wi-Fi d'un côté ou de l'autre, ou d'autre trafic sur le réseau.",
