"netdoctor.load_latency.balloons.detail": "La PS5 répond en {idle} ms quand le réseau est calme, mais en {loaded} ms pendant l'envoi d'un fichier. Un routeur ou une liaison Wi-Fi qui retient trop de données ralentit tous les transferts.",
