"netdoctor.mtu.mismatch.fix": "Utilisez 1500, la taille habituelle, des deux côtés : désactivez les jumbo frames sur cet ordinateur et réglez le MTU de la PS5 sur automatique dans les paramètres avancés de sa connexion Internet.",
