stop: "Arrêter",
activity_description_v2: "Tout ce que l'application fait et a fait sur vos consoles : envois, téléchargements, installations et opérations sur les fichiers. Arrêtez-en ou relancez-en une d'ici. Les 100 dernières sont conservées, même après un redémarrage.",
fw_spoof_subtitle_v2: "Vérifie si la version de firmware annoncée par cette PS5 a été modifiée par un payload d'usurpation, pour connaître sa vraie version avant d'installer quelque chose qui en dépend.",
health_subtitle_v2: "Vérifie que la PS5, cette application et le réseau entre elles fonctionnent, indique quoi corriger sinon, et mesure la vitesse de transfert des fichiers entre elles.",
remotePlay_subtitle_v2: "Configurez cette PS5 pour la Lecture à distance et obtenez le code PIN qui y associe l'application PS Remote Play.",
saves_description_v2: "Données de sauvegarde sur la PS5, une entrée par jeu. Sauvegardez les parties d'un jeu dans un .zip sur cet ordinateur et restaurez-les plus tard.",
shell_description_v2: "Saisissez des commandes exécutées sur la PS5, dans le processus de l'assistant. Pour un usage avancé. La sortie est limitée à 256 Ko par commande ; les flèches haut et bas rappellent les commandes précédentes.",
"arcpkg.links.go": "Télécharger {count} fichier(s)",
"arcpkg.links.help": "Collez le lien direct vers l'archive, ou vers chaque partie d'une archive découpée, un par ligne. Les fichiers sont téléchargés sur cet ordinateur (Downloads/ps5upload), qui doit avoir de la place pour tous ; les paquets qu'ils contiennent sont ensuite décompressés sur la PS5 comme ci-dessus.",
"arcpkg.links.kept": "{count} fichier(s) téléchargé(s) se trouvent dans {dir}. Ils sont conservés pour pouvoir relancer l'installation ; supprimez-les quand vous avez terminé.",
"arcpkg.links.progress": "Téléchargement du fichier {n} sur {count} vers cet ordinateur…",
"arcpkg.links.title": "L'archive est derrière des liens de téléchargement",
"arcpkg.noFirstPart": "Les fichiers ont été téléchargés, mais aucun n'est la première partie d'une archive (.zip, .7z, .rar ou .part1.rar). Vérifiez les liens.",
"fpkg.image.done": "Image de jeu écrite et relue. Copiez-la sur un disque de la PS5 (Téléverser) et ShadowMount+ la montera.",
"fpkg.image.what": "Un seul fichier à copier sur un disque de la PS5, que ShadowMount+ monte et affiche sur l'écran d'accueil. Rien n'est installé.",
"fpkg.image.folderOnly": "Seul un dossier de jeu de cet ordinateur peut devenir une image de jeu.",
"fpkg.image.folderOnly_v2": "Seul un dossier de jeu (sur cet ordinateur, un serveur enregistré ou la PS5) peut devenir une image de jeu.",
"fpkg.image.folderOnly_v4": "Seul un dossier de jeu, une image de jeu ou une archive (.zip, .7z, .rar) contenant un jeu peut devenir une image de jeu ; une archive est d'abord décompressée dans le dossier de sortie.",
"fpkg.card.make": "② Quoi créer",
