"fpkg.make.pkg_title": "Un paquet (.pkg)",
"fpkg.make.pkg_body": "S'installe sur la PS5 comme un jeu du store, diffusé depuis ici ou envoyé d'abord. Les jeux PS4 fonctionnent sur tout firmware ; les jeux PS5 jusqu'au 11.60.",
"fpkg.make.image_title": "Une image de jeu",
"fpkg.make.image_body": "Un fichier sur un disque de la PS5 que ShadowMount+ monte et affiche sur l'écran d'accueil. Rien n'est installé, et il fonctionne sur les firmwares où un paquet PS5 ne fonctionne pas.",
"fpkg.make.recommended": "Recommandé",
"fpkg.make.recommended_fw": "Recommandé sur FW {fw}",
"fpkg.make.pick_game": "Vérifiez un jeu sous ① et le meilleur choix pour votre PS5 sera indiqué.",
"fpkg.make.why_image": "Ce jeu PS5 s'installerait en paquet mais ne fonctionnerait pas sur FW {fw} ; en image, oui.",
"fpkg.make.why_pkg": "Un paquet est le choix habituel : il s'installe et fonctionne comme tout autre jeu.",
