connection_payload_engine_unreachable: "L'application n'a pas pu joindre son propre moteur sur cet ordinateur, elle ne peut donc pas savoir si l'assistant a démarré sur la PS5. Ce n'est pas un problème de la PS5 : l'avis en haut de la fenêtre en donne la raison et peut redémarrer le moteur. Appuyez ensuite à nouveau sur Envoyer l'assistant. ({error})",
"engine_problem.missing.fix": "Restaurez ps5upload-engine depuis la quarantaine de votre antivirus (ou autorisez-le), ou réinstallez l'application.",
"engine_problem.missing.why": "Le programme du moteur manque dans le dossier de l'application. Les logiciels de sécurité le mettent parfois en quarantaine.",
"engine_problem.port.fix": "Appuyez sur Redémarrer le moteur. Si cela échoue, autorisez ps5upload-engine dans votre pare-feu ou antivirus, puis redémarrez l'application.",
"engine_problem.port.why": "Quelque chose occupe l'adresse du moteur ({url}) sans répondre : un autre programme sur ce port, ou un logiciel de sécurité qui bloque les connexions vers lui.",
"engine_problem.proxy.fix": "Désactivez le proxy ou l'outil VPN pour les adresses locales (127.0.0.1), ou lancez l'application sans le réglage http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "Les requêtes au moteur sont parties vers un proxy configuré sur cet ordinateur au lieu du moteur.",
"engine_problem.remote.fix": "Vérifiez que le moteur (conteneur Docker ou autre ordinateur) tourne et est joignable à cette adresse, ou changez-la dans Paramètres.",
"engine_problem.remote.why": "Le moteur que cette application doit utiliser ({url}) ne répond pas.",
"engine_problem.restart": "Redémarrer le moteur",
"engine_problem.slow.fix": "Appuyez sur Redémarrer le moteur. Un pare-feu ou antivirus qui filtre les connexions locales peut aussi en être la cause : autorisez ps5upload-engine.",
"engine_problem.slow.why": "Le moteur tourne mais ne répond pas.",
"engine_problem.stopped.fix": "Appuyez sur Redémarrer le moteur. S'il s'arrête de nouveau, l'écran Journaux indique pourquoi.",
"engine_problem.stopped.why": "Le moteur ne tourne pas : il s'est arrêté ou n'a jamais démarré.",
"engine_problem.title": "L'application ne joint pas son moteur sur cet ordinateur",
"engine_problem.web.fix": "Vérifiez que le serveur (conteneur Docker) tourne, puis rechargez cette page.",
"engine_problem.web.why": "Cette page a perdu la connexion au serveur ps5upload dont elle provient.",
gate_engine_down_body_v2: "Cet écran a besoin du moteur de l'application, qui ne répond pas. L'avis en haut de la fenêtre en donne la raison et peut le redémarrer.",
"profile.np.body": "Fait que la PS5 traite le compte connecté comme connecté au PlayStation Network, sans contacter Sony. Certaines fonctions de la console ne s'ouvrent qu'à un compte connecté, dont la Lecture à distance. Utilise np-fake-signin d'earthonion, récupéré depuis la page du projet quand vous appuyez sur le bouton.",
"profile.np.confirm_title": "Connecter ce compte ?",
"profile.np.failed": "La connexion ne s'est pas exécutée",
"profile.np.fetching": "Récupération de np-fake-signin…",
"profile.np.sending": "Envoi à la PS5…",
"profile.np.sent": "np-fake-signin {version} s'est exécuté sur la PS5. Redémarrez la PS5 pour terminer ; le compte apparaît alors connecté, et Paramètres > Système > Lecture à distance peut être activé.",
"profile.np.sign_in": "Connecter",
"profile.np.state_loading": "Lecture du compte…",
"profile.np.state_no_slot": "Aucun compte ci-dessus ne s'appelle {user}, donc np-fake-signin s'arrêterait. Donnez au compte le même nom que l'utilisateur connecté, ou activez-en un pour lui.",
"profile.np.state_no_user": "Aucun utilisateur n'est connecté sur la PS5. Connectez-vous au profil voulu, puis revenez.",
"profile.np.state_not_activated": "{user} (compte {slot}) n'a pas encore d'identifiant de compte. Activez-le d'abord dans Comptes ci-dessus.",
"profile.np.state_ready": "Prêt : {user} (compte {slot}) est activé.",
"profile.np.step_activate": "Le compte a besoin d'un identifiant de compte. Un compte lié au PSN en a un ; sinon activez-le dans Comptes ci-dessus (activation hors ligne).",
"profile.np.step_run": "Appuyez sur Connecter pendant que cet utilisateur est connecté sur la PS5. Il s'exécute une fois puis se ferme.",
"profile.np.title": "Se connecter au PlayStation Network (hors ligne)",
