"fpkg.image.lz4_profile_clear": "Utiliser le profil intégré",
"fpkg.image.lz4_install_runtime": "Mettre ampr_emu 0.4.2.1 dans l'image",
"fpkg.image.lz4_install_runtime_body": "{reason}. L'image reçoit l'ampr_emu 0.4.2.1 de drakmor en fakelib/libSceAmpr.sprx (téléchargé une fois depuis sa release GitHub et vérifié contre une empreinte connue) ; la copie du jeu reste à côté en libSceAmpr.sprx.orig.",
"fpkg.image.lz4_no_ampr": "Ce jeu ne lit pas ses fichiers via AMPR, rien ne pourrait donc servir des paquets d'assets. Compressez-le plutôt en .ffpfsc : ShadowMount+ le décompresse pour n'importe quel jeu.",
"fpkg.image.verify_chunk": "Relecture de contrôle, par lecture",
"fpkg.image.verify_chunk_body": "Après l'écriture, l'image est relue et vérifiée. 8 Mio était le plus rapide à la mesure ; essayez une autre valeur si votre disque n'est pas d'accord. Le contrôle lui-même est identique quelle que soit la taille.",
