install_hint_setup_exe: "L'installateur s'est ouvert : suis-le, il met à jour PS5Upload sur place.",
install_path_fallback_hint: "Un dernier recours pour un paquet déjà présent sur la PS5, quand la PS5 le refuse depuis son propre stockage et ne peut pas non plus le récupérer depuis cet ordinateur. Utilisé uniquement pour un jeu de base non installé, il ne peut donc rien supprimer. Non éprouvé : cela a fonctionné sur le firmware 11.20 et c'est refusé sur 13.60. Si tu l'essaies, merci d'indiquer si cela a fonctionné.",
