"minion_lan_hint": "Désactivé : seul le navigateur de la PS5 l’ouvre. Activé : un téléphone, une tablette ou un ordinateur du même réseau peut aussi l’ouvrir, donc toute personne sur ce réseau. À activer uniquement chez vous.",
"minion_open_here": "Ouvrir ici",
"minion_remove_note": "Retirer désactive Minion et supprime ce qu’il conserve sur la PS5 : ses favoris et dossiers récents de Fichiers, son cache de la Bibliothèque de jeux et son journal de manette. Les partages réseau, les cheats et les sauvegardes restent ; l’app PC les utilise aussi.",
"minion_remove": "Retirer Minion de cette PS5…",
"minion_remove_title": "Retirer PS5Upload Minion ?",
"minion_remove_confirm": "Sa vignette de l’écran d’accueil et sa page disparaissent, et ses propres fichiers sur la PS5 sont supprimés. L’assistant le garde désactivé à partir de maintenant. Vous pouvez le réactiver ici à tout moment.",
