"fs_drag_hint_move": "Faites glisser des fichiers et dossiers hors de la fenêtre pour les copier sur cet ordinateur, ou glissez-les dedans pour les copier ici. Maintenez Alt (⌥ Option sur un Mac) en glissant pour les déplacer dans un dossier d’ici.",
"fs_drag_hint": "Faites glisser des fichiers et dossiers hors de la fenêtre pour les copier sur cet ordinateur, ou glissez-les dedans pour les copier ici.",
"fs_browser_drop_folder": "Impossible de déposer des dossiers dans un navigateur",
"fs_browser_drop_folder_body": "Déposez les fichiers qu’il contient, ou utilisez l’app de bureau pour copier des dossiers entiers.",
"collection.send_free_space": "Libérer de l’espace",
"game_show_in_files": "Afficher dans Fichiers",
"game_search_files": "Rechercher dans les fichiers de ce jeu",
"installed_uninstall_no_copy": "Votre Collection sur cet ordinateur n’a aucune copie de ce jeu : conservez son package quelque part avant de le désinstaller.",
"connection_send_payload_moved": "Envoyer un autre payload (kstuff, etaHEN, n'importe quel .elf) ? C'est dans Payloads → Envoyer un payload. Cet écran n'envoie que l'assistant PS5Upload.",
"connection_send_payload_open": "Ouvrir Envoyer un payload",
"upload_elf_title": "C'est un payload (.elf), pas un jeu",
"upload_elf_body": "L'envoyer ne fait que copier le fichier. ShadowMount+ prend en charge les dossiers de jeu (avec eboot.bin et sce_sys) et les images de jeu, jamais un .elf, il n'apparaîtra donc pas sur l'écran d'accueil. Pour l'exécuter, envoyez-le plutôt au chargeur de la console. Ce qu'il faut envoyer, c'est une app homebrew fournie en image .ffpkg ou .exfat, ou en dossier avec eboot.bin.",
"netdoctor.hint.below_test": "Cet envoi tourne à {speed}, bien en dessous des {expected} mesurés par le test de vitesse.",
"netdoctor.hint.runs_at": "Cet envoi tourne à {speed}.",
"netdoctor.hint.cause_source": "Ce qui le freine, c'est la lecture des fichiers sur cet ordinateur, pas le réseau : une clé ou un disque USB, un disque dur, un partage réseau (NAS) ou la décompression d'une archive est plus lent que la liaison. Copier d'abord le jeu sur un SSD interne, ou envoyer les fichiers d'une archive une fois décompressés, donne la pleine vitesse.",
"netdoctor.hint.cause_disk": "Ce qui le freine, c'est le stockage de la PS5, pas le réseau : un disque USB externe, un disque presque plein ou des milliers de petits fichiers (chacun prend son propre temps) écrivent plus lentement que ce que la liaison fournit. Une image de jeu (.ffpkg ou .exfat) part en un seul fichier.",
"netdoctor.hint.cause_workers": "La PS5 écrit encore ce qu'elle a reçu, elle n'attend pas le réseau. Avec beaucoup de petits fichiers, chacun prend son propre temps ; une image de jeu (.ffpkg ou .exfat) part en un seul fichier.",
"netdoctor.hint.cause_cap": "Ce qui le freine, c'est la limite de vitesse d'envoi (environ {cap} Mio/s, sur cet écran et dans Réglages). Mettez-la à 0 pour la supprimer.",
"profile.np.confirm_body_v2": "np-fake-signin écrit sur la PS5 les fichiers et réglages de connexion au PlayStation Network pour {user}. Rien n'est envoyé à Sony. Redémarrez la PS5 ensuite.",
"profile.np.side_effect": "Effet secondaire connu : ensuite, certaines consoles demandent de « Désactiver temporairement les restrictions de la console PS5 » avant d'ouvrir un jeu, et Paramètres > Utilisateurs et comptes > Autre > Se déconnecter peut rester grisé. L'app garde d'abord sur la PS5 une copie de tout ce que np-fake-signin modifie, donc Annuler la connexion ici remet tout en place.",
"profile.np.backing_up": "Copie des réglages actuels du compte sur la PS5…",
"profile.np.backup_failed": "La PS5 n'a pas pu garder une copie des réglages du compte, np-fake-signin n'a donc pas été lancé. Remplacez l'assistant par la version de cette app et réessayez. ({error})",
"profile.np.step_restart_v2": "Redémarrez la PS5. Pour annuler plus tard, appuyez ici sur Annuler la connexion, puis redémarrez.",
"profile.np.undo": "Annuler la connexion",
"profile.np.undo_hint": "Une copie des réglages de ce compte d'avant la connexion est gardée sur la PS5 ; ceci la remet en place.",
"profile.np.undo_confirm_title": "Annuler la connexion ?",
"profile.np.undo_confirm_body": "Remet les réglages et fichiers de {user} tels qu'ils étaient avant np-fake-signin. Redémarrez la PS5 ensuite. Les fonctions qui demandent un compte connecté, dont la Lecture à distance, peuvent ne plus s'ouvrir jusqu'à une nouvelle connexion.",
"profile.np.undoing": "Remise en place des réglages…",
"profile.np.undone": "Remis en place ({count} réglages et fichiers). Redémarrez la PS5 pour terminer.",
"profile.np.no_backup": "Ce compte porte les réglages du modèle de np-fake-signin (date de naissance 1983-04-12, indicateur d'adulte hors ligne désactivé) et aucune copie d'avant n'est gardée sur cette PS5 : l'app ne peut donc pas l'annuler. Si la PS5 demande maintenant de désactiver temporairement les restrictions de la console avant d'ouvrir un jeu : Paramètres > Famille et contrôle parental > Restrictions de la console PS5 (code 0000 sauf si vous l'avez changé), et levez les restrictions là.",
"linkdl.lz4_title": "Ce lien est compressé en LZ4",
"linkdl.image_title": "Ce lien est une image de jeu",
"linkdl.lz4_help": "ps5upload peut le décompresser pendant le téléchargement : la PS5 reçoit le fichier décompressé. Rien n'est stocké sur cet ordinateur, et la PS5 n'a besoin de place que pour le fichier décompressé.",
"linkdl.lz4_unpack": "Décompresser en route",
"linkdl.lz4_unpack_hint": "Désactivé : le fichier .lz4 est enregistré tel quel sur la PS5.",
"linkdl.image_hint": "Une image de jeu {kind}. ShadowMount+ la monte telle quelle depuis un dossier qu'il analyse, comme homebrew sur un disque. Le fichier n'y apparaît qu'une fois complet.",
"pm_add_failed": "Impossible d'enregistrer {name} dans Payload Manager",
"pm_catalogue_match": "Catalogue : {name}",
"pm_replace_tooltip": "Payload Manager ne garde aucune version pour un payload ajouté à la main, donc ps5upload ne peut pas savoir si celui-ci est plus ancien. Remplacer enregistre la version du catalogue à sa place en gardant sa position dans la liste de démarrage ; ensuite, les mises à jour sont proposées ici.",
"pm_replace_with": "Remplacer par {tag}",
