"payloads_description_running": "Les programmes qui tournent sur la PS5 en ce moment, et les ports utilisés avec ce qui y écoute d'habitude. Vous pouvez arrêter ou redémarrer un programme ; prudence avec les processus système, arrêter le mauvais peut figer la console.",
"accounts_title": "Comptes",
