"ps4move_badge": "Expérimental",
"ps4move_experimental": "Expérimental : remettre des sauvegardes au format PS4 sur une PS5 ne marche pas toujours, et un jeu peut ne pas en charger une. Essaie d'abord un seul jeu ; sa sauvegarde PS5 est gardée et peut être remise depuis les sauvegardes du jeu.",
"ps4move_safety": "La PS4 est seulement lue, jamais modifiée. Ses sauvegardes sont d'abord copiées sur cet ordinateur. Sur la PS5, seuls les jeux choisis sont touchés, la sauvegarde de chacun est sauvegardée avant d'être remplacée, et rien d'autre (utilisateurs, fichiers système, trophées) n'est modifié.",
"ps4move_need_dir": "Choisis d'abord un dossier dans Sauvegardes automatiques ci-dessus : les sauvegardes de la PS4 y sont gardées, et chaque sauvegarde de la PS5 avant d'être remplacée.",
