"rp_fit_short_fill": "Remplir",
"rp_set_next_start_v2": "La résolution et la fréquence d'images s'appliquent au prochain démarrage. La taille de l'image s'applique tout de suite ; elle se voit en plein écran, où la forme de l'écran peut différer de celle de l'image.",
"rp_browser_best": "Remote Play fonctionne mieux dans Chrome ou Edge",
"rp_browser_firefox": "Dans Firefox, Échap quitte toujours le plein écran, donc ne peut pas y être le ○ de la manette, et l'image dans l'image n'est pas disponible.",
"rp_browser_safari": "Dans Safari, Échap quitte toujours le plein écran, donc ne peut pas y être le ○ de la manette, et l'image dans l'image n'affiche que l'image.",
"rp_browser_other": "Il est conçu et testé pour eux. Ici, Échap comme ○ de la manette en plein écran et l'image dans l'image peuvent ne pas marcher.",
"rp_browser_other_mobile": "Il est conçu et testé pour Chrome sur Android.",
