"rp_audio_hint": "Craquements ou coupures sur un réseau chargé : choisissez Stable. En filaire, Délai minimal est idéal.",
"rp_set_session": "Session",
"rp_keep_alive": "Continuer à jouer après avoir quitté cet écran ou l'app",
