"rp_keep_5m": "5 minutes",
"rp_keep_10m": "10 minutes",
"rp_keep_hint": "Les autres écrans gardent le flux actif ; c'est le délai d'attente sans fenêtre qui l'affiche (fermée ou rechargée) avant qu'il s'arrête.",
"rp_game_mode_mac": "Pendant que vous jouez, l'ordinateur et l'écran restent éveillés. Le plein écran active aussi le mode Jeu (macOS 14 et versions ultérieures).",
"rp_game_mode_ios": "Le mode Jeu s'active tant que l'app occupe l'écran (iOS et iPadOS 18 et versions ultérieures).",
"rp_game_mode_windows": "Pendant que vous jouez, l'ordinateur et l'écran restent éveillés. Windows ne permet pas à une app d'activer le mode Jeu ; voir la FAQ.",
"rp_game_mode_linux": "Pendant que vous jouez, l'ordinateur et l'écran restent éveillés, et GameMode (gamemoded) s'active s'il est installé.",
"rp_game_mode_android": "Pendant que vous jouez, l'écran reste allumé, l'appareil garde une vitesse stable quand il le peut, et un téléviseur en HDMI passe en mode jeu sur demande.",
"rp_set_controls": "Commandes",
