"rp_capture_pointer_hint": "Esc le réaffiche.",
"rp_rumble": "Vibration de la manette",
"rp_mic_setting": "Microphone (expérimental)",
"rp_mic_setting_hint": "Ajoute un bouton micro pour le chat vocal. S’applique au prochain démarrage.",
"rp_touch_controls": "Manette à l'écran",
"rp_touch_auto": "Sur écran tactile",
"rp_touch_on": "Toujours",
"rp_touch_off": "Jamais",
"rp_controls_hint": "Une manette fonctionne aussi : branchez-la ou associez-la à cet appareil. Shift + glisser sur l'image = un doigt sur le pavé tactile.",
"rp_settings": "Paramètres",
"rp_running_elsewhere": "La Lecture à distance est active sur {name}",
"rp_show_here": "Afficher ici",
"rp_running_elsewhere_body": "Il a été lancé depuis une autre fenêtre ou avant le rechargement de cette page, et continue.",
"rpg_user_title": "Connecter un utilisateur sur la PS5",
"rpg_user_body": "Sur la console, choisissez l'utilisateur avec lequel vous jouerez. Personne n'a besoin de rester devant l'écran, mais l'utilisateur doit être connecté. Prenez un utilisateur sans code de connexion : un code empêche la connexion automatique quand la console se réveille.",
"rpg_account_title": "Donner un ID de compte à cet utilisateur",
"rpg_account_body": "La Lecture à distance s'associe via un ID de compte. Un utilisateur lié au PlayStation Network en a déjà un ; un utilisateur hors ligne doit en recevoir un dans Utilisateurs ci-dessus (n'importe quel ID convient ; notez-le, les sauvegardes faites ensuite y sont liées).",
"rpg_signin_title": "Connecter le compte au PlayStation Network (hors ligne)",
"rpg_signin_body": "La PS5 ne laisse utiliser la Lecture à distance qu'à un compte connecté. Si le réglage Lecture à distance de la console est grisé, lancez la connexion hors ligne ci-dessous (rien n'est envoyé à Sony), puis redémarrez la PS5. C'est réversible.",
"rpg_signin_fix": "Aller à la connexion",
"rpg_service_title": "Activer la Lecture à distance",
"rpg_service_body": "Paramètres › Système › Lecture à distance › Activer la Lecture à distance. L'app peut l'activer pour vous et, à partir du firmware 10.00, l'autoriser aussi pour cet utilisateur.",
"rpg_rest_title": "Permettre de réveiller la PS5 depuis le mode repos",
"rpg_rest_body": "Paramètres › Système › Économie d'énergie › Fonctions disponibles en mode repos : activez « Rester connecté à Internet » et « Autoriser l'allumage de la PS5 via le réseau ». Sans eux, une console en mode repos ne peut pas être réveillée et son réseau s'endort après quelques secondes. Seule la console peut afficher ces réglages.",
"rpg_pair_title": "Associer cette app à la console",
"rpg_pair_body": "Connexion › Réveiller et connecter › Configurer. Un clic enregistre cette app auprès de la PS5 (comme l'association de l'app PS Remote Play) et garde ses clés sur cet ordinateur. Le streaming, le réveil et la connexion les utilisent tous ; recommencez après une réinitialisation de la console ou un changement d'utilisateur.",
"rpg_play_title": "Jouer",
"rpg_play_body": "Ouvrez Lecture à distance et appuyez sur Démarrer : l'app réveille la console si elle est en repos, la connecte et lance le streaming. Jouez avec une manette branchée à cet ordinateur, le clavier ou le tactile. Pour utiliser plutôt l'app PS Remote Play de Sony ou chiaki-ng, demandez un PIN ci-dessous et saisissez-le là-bas.",
"rpg_play_fix": "Ouvrir Lecture à distance",
"rpg_title": "Configurer la Lecture à distance",
"rpg_progress": "{done} étapes vérifiées sur {n} terminées",
"rpg_on_console": "à vérifier sur la console",
"rpg_trouble": "Si ça ne fonctionne toujours pas",
"rpg_t_start_q": "Démarrer est grisé sur l'écran Lecture à distance.",
"rpg_t_start_a": "Cette app n'est pas encore associée à cette console : faites l'étape 6 (Connexion › Réveiller et connecter › Configurer).",
"rpg_t_pair_q": "La configuration de l'association indique qu'aucun utilisateur connecté n'a de compte activé.",
"rpg_t_pair_a": "Étapes 1 et 2 : connectez un utilisateur sur la PS5 et donnez-lui un ID de compte, puis réessayez.",
"rpg_t_grey_q": "Le réglage Lecture à distance de la PS5 elle-même est grisé.",
"rpg_t_grey_a": "Le compte n'est pas connecté au PlayStation Network. Lancez la connexion hors ligne (étape 3) et redémarrez la PS5.",
"rpg_t_wake_q": "La console ne se réveille pas, ou se réveille mais reste sur l'écran de sélection d'utilisateur.",
"rpg_t_wake_a": "Vérifiez l'étape 5 sur la console. Un utilisateur avec un code de connexion empêche la connexion automatique. Si la console a été réinitialisée ou l'utilisateur a changé, configurez à nouveau l'association (étape 6).",
"rpg_t_black_q": "L'image reste noire, saccade, ou le son grésille.",
"rpg_t_black_a": "Utilisez une connexion filaire ou le Wi-Fi 5 GHz pour la PS5 et cet ordinateur, et essayez 720p ou 30 fps dans les paramètres de la Lecture à distance. Un pare-feu sur cet ordinateur doit autoriser l'app sur le réseau local (la Lecture à distance utilise les ports TCP et UDP 9295–9304). Dans un navigateur, utilisez un Chrome, Edge ou Safari récent : l'image a besoin de WebCodecs.",
"rpg_t_busy_q": "Il est indiqué que la PS5 termine encore la dernière session, ou qu'une autre console diffuse.",
"rpg_t_busy_a": "Une seule console diffuse à la fois, et la PS5 a besoin de jusqu'à 30 secondes après la fin d'une session. Arrêtez l'autre flux, patientez un instant, puis appuyez à nouveau sur Démarrer.",
"rpg_t_restrict_q": "Après la connexion hors ligne, les jeux demandent de désactiver les restrictions de la console.",
"rpg_t_restrict_a": "Utilisez Annuler la connexion sur cette page et redémarrez, ou levez la restriction dans Paramètres › Famille et contrôle parental › Restrictions de la console PS5 (code 0000 sauf si vous l'avez changé).",
