"rp_keys_body3": "Cliquez sur l’image pour jouer au clavier ; Échap rend le pointeur. Double-clic pour le plein écran ; là, un appui bref sur Échap fait Rond et le maintenir quitte le plein écran. Touches, son et plus dans Réglages.",
