"dump_decrypt_risk": "Le déchiffrement peut figer la console",
"dump_decrypt_risk_body": "Pour déchiffrer, l'assistant remplace brièvement, pour chaque exécutable, une partie du système utilisée par tous les programmes. Si le jeu lit un fichier à ce moment, la console peut se figer et nécessiter un arrêt forcé. Restez sur l'écran titre du jeu pendant l'opération. Firmware jusqu'à 13.60 uniquement ; sur un firmware plus récent, le dump est une simple copie.",
