"send_title_v2": "Envoyer et installer",
"collection.send_many_body_v2": "Chaque PS5 reçoit ce qui lui manque : le paquet du jeu, ou son dossier, son image ou son archive, plus les mises à jour plus récentes et les DLC des jeux qu'elle a. Les paquets sont diffusés depuis cet ordinateur ; le reste est envoyé sur le disque choisi dans « Envoyer et installer », dans le dossier homebrew.",
"first_run_step4_body_v3": "Insérez dans votre PS5 une clé USB contenant des images de jeux .ffpkg et ShadowMount+ les montera automatiquement — elles apparaîtront dans Jeux. Pour envoyer d'autres fichiers ou installer des paquets .pkg, utilisez « Envoyer et installer ».",
"first_run_go_upload_v2": "Ouvrir « Envoyer et installer »",
"fpkg.aboutFake_v2": "Le résultat est un faux paquet : la console doit donc avoir la prise en charge des faux paquets chargée avant de l'installer : kstuff (la version avec prise en charge des faux paquets PS5), a53_ppr_install_fast.elf et shadowmountplus.elf, dans cet ordre. « Envoyer et installer » indique la même chose à côté de ses boutons d'installation.",
"fpkg.openUpload_v2": "Ouvrir « Envoyer et installer »",
"connection_step3_hint_v3": "Ouvrez « Envoyer et installer » et déposez-y un dossier de jeu, une image .exfat ou .ffpkg, ou un paquet .pkg. Les images et dossiers envoyés apparaissent sur la page du jeu dans Jeux, où Monter les place sur l'écran d'accueil de la PS5.",
"connection_go_upload_v2": "Ouvrir « Envoyer et installer »",
"netdoctor.speed_cap.on.fix_v2": "Retirez la limite dans « Envoyer et installer » si vous n'en avez pas besoin.",
"payloads_fpkg_ppr_note_v2": "L'installation de faux paquets nécessite aussi a53_ppr_install_fast.elf, absent de cette liste : aucun téléchargement n'est publié, il se compile à partir des sources sur GitHub. « Envoyer et installer » liste tout ce dont les faux paquets ont besoin, dans l'ordre.",
"fs_extract_next_pkgs_v2": "Il contient {n} paquet(s) : installez-les depuis « Envoyer et installer », ou depuis leur ligne ici.",
"game_hub_no_addons_v2": "Aucun paquet DLC préparé pour ce titre. Envoyez-en un depuis « Envoyer et installer ».",
"game_hub_open_install_v2": "Ouvrir « Envoyer et installer »",
"bandwidth_cap_off_hint_v3": "Aucune limite. Fixez-en une si les envois saturent votre Wi-Fi/LAN et ralentissent les autres appareils. Elle s'applique à chaque envoi, depuis « Envoyer et installer », la file et Fichiers, dès le prochain.",
"queue_links_cleared_body_v2": "{n} lien(s) d'installation n'ont pas été conservés après le redémarrage — les liens ne sont jamais enregistrés sur le disque. Ajoutez-les à nouveau depuis « Envoyer et installer ».",
"game_hub_no_updates_v2": "Aucun paquet de mise à jour préparé pour ce titre. Envoyez-en un depuis « Envoyer et installer ».",
"pkglib.fpkgsupport.firmware": "Les faux paquets PS5 (PS5 FPKG) ne sont pas encore pris en charge sur un firmware postérieur à 11.60 : ils s'installent, mais le jeu ne démarre pas. Les faux paquets PS4 fonctionnent.",
"upload_drop_here3": "Déposez ou choisissez des paquets, jeux, images disque, archives ou tout autre fichier",
"upload_pick_here_mobile3": "Choisissez des paquets, jeux, images disque, archives ou tout autre fichier",
"upload_drop_kind_pkg": "Paquets (.pkg, .fpkg) : installés comme jeu, mise à jour ou DLC, diffusés depuis ici ou envoyés d'abord.",
"upload_drop_kind_game": "Dossiers de jeu et dumps de jeux : copiés sur la PS5 ; ils peuvent aller sur l'écran d'accueil.",
"upload_drop_kind_image": "Images disque (.exfat, .ffpkg, .ffpfs, .ffpfsc) : copiées sur la PS5 ; elles peuvent être montées.",
"upload_drop_kind_archive": "Archives (.zip, .7z, .rar) : extraites sur la PS5.",
"upload_drop_kind_other": "Tout autre fichier ou dossier : copié tel quel.",
"upload_other_ways": "Ou installez un paquet :",
"queue_stream_fail_hint": "« Diffuser et installer » fait récupérer le paquet par la PS5 depuis cet ordinateur. Si l'échec persiste, autorisez ps5upload dans le pare-feu de cet ordinateur sur le réseau local pour que la PS5 puisse l'atteindre, ou utilisez « Réessayer par envoi », qui copie d'abord le paquet sur la PS5 puis l'installe.",
"err_install_enoent_generic_v2": "L'installateur de Sony n'a pas pu ouvrir un fichier dont il avait besoin pendant l'installation (erreur noyau 0x80020002 = ENOENT). S'il s'agit d'un pkg de DLC, le jeu de base n'est pas encore installé — installez d'abord la base. Sinon, le paquet préparé a peut-être été supprimé entre l'envoi et l'installation ; réessayez l'installation une fois. Si l'échec persiste, installez-le avec « Diffuser et installer » dans « Envoyer et installer », qui envoie le paquet directement depuis cet ordinateur au lieu de le copier d'abord sur la console.",
"upload_convert_first": "Convertir d'abord",
"batch_convert_first_hint": "Ouvrir les jeux, dossiers et images cochés dans l'Atelier, pour d'abord en faire des paquets, des images ou des dossiers",
"add_sources_pick_folders": "Choisir un ou plusieurs dossiers",
"add_sources_pick_files": "Choisir un ou plusieurs fichiers",
"workshop_add_locked": "Un jeu est en cours de création : les jeux choisis maintenant attendent dans la file.",
"workshop_add_hint": "Choisissez un jeu pour le vérifier ici. Plusieurs jeux, ou un dossier de jeux, vont dans la file et sont créés l'un après l'autre.",
"workshop_description_v2": "Changez le format d'un jeu avant qu'il n'aille sur la PS5 : créez un paquet (.pkg), une image de jeu (.exfat, .ffpkg ou le plus petit .ffpfsc) ou un simple dossier, ou regardez à l'intérieur d'une image ou d'un paquet et modifiez ses fichiers. Le travail se fait sur cet ordinateur. Pour envoyer un jeu tel quel, utilisez {send}.",
"cq_title_v2": "⑤ File d'attente",
"cq_about": "Créés l'un après l'autre sur cet ordinateur, chacun selon les réglages de ②, ③ et ④ au moment de son ajout. Ajoutez-en d'autres sous ①, même pendant que la file tourne ; modifiez un jeu en attente avec son bouton d'options.",
"cq_then_send": "Un jeu à installer ou à envoyer passe dans la file de {send} une fois créé.",
"cq_open_send": "Ouvrir {send}",
"backup_alike_toggle": "{count} copies identiques depuis le {since}. Affichez-les pour restaurer une copie plus ancienne.",
"add_sources_no_picker": "Cette version ne peut pas parcourir cette machine — saisissez un chemin visible par le moteur.",
"collection.empty_body_v2": "Les paquets, dossiers de jeu, images de jeu et archives qu'il contient sont trouvés et regroupés par jeu. Rien n'est modifié dans le dossier. Un dossier sur cet appareil, un disque externe ou un dossier sur un NAS ou un serveur (SMB, FTP, SFTP, WebDAV) conviennent.",
"collection.add_nas_folder": "Depuis un NAS ou un serveur",
