"queue_auto_start": "Démarrer la file quand vous ajoutez quelque chose",
"queue_auto_start_tooltip": "Activé : « Installer », « Envoyer maintenant » et « Envoyer » démarrent toute la file de cette console, dans l’ordre. Désactivé : ils ajoutent seulement à la file, et rien ne s’exécute tant que vous n’appuyez pas sur « Démarrer la file ».",
"queue_auto_start_hint": "Activé : « Installer », « Envoyer maintenant » et « Envoyer » démarrent toute la file de la console, dans l’ordre — pas seulement ce que vous venez d’ajouter. Désactivé : ils ajoutent seulement à la file, et rien ne s’exécute tant que vous n’appuyez pas sur « Démarrer la file ». Activé par défaut.",
